from datetime import datetime

def calculate_time_to_lunch(meetings):
    # Find the meeting before lunch
    meeting_before_lunch = None
    for meeting in meetings:
        if meeting['title'] == 'Team Sync':
            meeting_before_lunch = meeting
            break

    # Calculate the time to lunch
    if meeting_before_lunch:
        end_time = datetime.strptime(meeting_before_lunch['end_time'], '%Y-%m-%d %H:%M:%S')
        lunch_start_time = datetime.strptime('2024-05-15 12:30:00', '%Y-%m-%d %H:%M:%S')
        time_to_lunch = lunch_start_time - end_time
        hours, remainder = divmod(time_to_lunch.seconds, 3600)
        minutes, _ = divmod(remainder, 60)
        return f'{hours:02d}:{minutes:02d}'
    else:
        return '00:00'

meetings = [
    {
        'title': 'Team Sync',
        'end_time': '2024-05-15 11:00:00'
    },
    {
        'title': 'Lunch with Sarah',
        'start_time': '2024-05-15 12:30:00'
    }
]

print(calculate_time_to_lunch(meetings))
